tools.example:
fig = uifigure('Name', 'Control Panel', 'Position', [200 200 480 320]);
lbl = uilabel(fig, 'Position', [20 260 200 22], 'Text', 'Gain:');
sld = uislider(fig, 'Position', [20 240 200 3], 'Limits', [0 10]);
sld.ValueChangedFcn = @(s, e) set(lbl, 'Text', sprintf('Gain: %.2f', s.Value));

fig = uifigure('Position', [100 100 500 320]);
g = uigridlayout(fig, [3 2]);
g.RowHeight = {30, '1x', 30};
g.ColumnWidth = {120, '1x'};
lbl = uilabel(g, 'Text', 'Signal');
lbl.Layout.Row = 1; lbl.Layout.Column = 1;
ax = uiaxes(g);
ax.Layout.Row = 2; ax.Layout.Column = [1 2];
plot(ax, 1:10, rand(1,10));

fig = uifigure('Position', [100 100 520 380]);
ax = uiaxes(fig, 'Position', [30 30 460 320]);
x = linspace(0, 10, 200);
plot(ax, x, sin(x));
hold(ax, 'on');
plot(ax, x, cos(x));
hold(ax, 'off');
title(ax, 'Signals');
legend(ax, 'sin', 'cos');

fig = uifigure('Position', [100 100 300 160]);
lbl = uilabel(fig, 'Position', [20 100 260 22], 'Text', 'count: 0');
lbl.UserData = 0;
btn = uibutton(fig, 'push', 'Position', [20 40 100 30], 'Text', 'Increment');
btn.ButtonPushedFcn = @(src, evt) set(lbl, ...
    'UserData', lbl.UserData + 1, ...
    'Text', sprintf('count: %d', lbl.UserData + 1));

fig = uifigure('Position', [100 100 360 200]);
uilabel(fig, 'Position', [20 150 120 22], 'Text', 'Sample rate (Hz):');
fld = uieditfield(fig, 'numeric', 'Position', [150 150 100 22], 'Value', 1000);
status = uilabel(fig, 'Position', [20 20 320 60], 'Text', 'Ready', ...
    'WordWrap', 'on', 'FontColor', [0.2 0.5 0.2]);

fig = uifigure('Position', [100 100 340 160]);
num = uieditfield(fig, 'numeric', 'Position', [20 100 120 22], ...
    'Limits', [0 100], 'Value', 10, 'ValueDisplayFormat', '%.1f %%');
txt = uieditfield(fig, 'text', 'Position', [20 60 200 22], ...
    'Placeholder', 'enter a label');
num.ValueChangedFcn = @(s, e) fprintf('changed %g -> %g\n', e.PreviousValue, e.Value);

fig = uifigure('Position', [100 100 320 140]);
dd = uidropdown(fig, 'Position', [20 80 180 22], ...
    'Items', {'Linear', 'Spline', 'PCHIP'}, ...
    'ItemsData', {'linear', 'spline', 'pchip'}, ...
    'Value', 'linear');
dd.ValueChangedFcn = @(s, e) fprintf('method = %s\n', s.Value);

fig = uifigure('Position', [100 100 300 240]);
files = {'run1.mat', 'run2.mat', 'run3.mat'};
lb = uilistbox(fig, 'Position', [20 60 200 140], ...
    'Items', files, 'Multiselect', 'on');
uibutton(fig, 'Position', [20 20 100 26], 'Text', 'Load', ...
    'ButtonPushedFcn', @(s,e) disp(lb.Value));

fig = uifigure('Position', [100 100 300 160]);
cbx = uicheckbox(fig, 'Position', [20 110 200 22], ...
    'Text', 'Apply smoothing', 'Value', true);
sld = uislider(fig, 'Position', [20 70 200 3], 'Limits', [1 51], 'Value', 11);
cbx.ValueChangedFcn = @(s, e) set(sld, 'Enable', matlab.lang.OnOffSwitchState(s.Value));

fig = uifigure('Position', [100 100 300 160]);
sw = uiswitch(fig, 'slider', 'Position', [60 80 60 26], ...
    'Items', {'Off', 'On'}, 'ItemsData', {false, true}, 'Value', false);
lmp = uilamp(fig, 'Position', [180 80 20 20], 'Color', 'red');
palette = [1 0 0; 0 0.8 0];
sw.ValueChangedFcn = @(s, e) set(lmp, 'Color', palette(double(s.Value) + 1, :));

fig = uifigure('Position', [100 100 420 260]);
ax = uiaxes(fig, 'Position', [20 80 380 160]);
x = linspace(0, 10, 400);
ln = plot(ax, x, sin(x));
sld = uislider(fig, 'Position', [40 50 340 3], 'Limits', [0.5 5], 'Value', 1);
sld.ValueChangingFcn = @(s, e) set(ln, 'YData', sin(e.Value * x));

fig = uifigure('Position', [100 100 300 140]);
uilabel(fig, 'Position', [20 80 120 22], 'Text', 'Filter order:');
spn = uispinner(fig, 'Position', [150 80 100 22], ...
    'Limits', [1 20], 'Step', 1, 'Value', 4, ...
    'RoundFractionalValues', 'on');
spn.ValueChangedFcn = @(s, e) fprintf('order = %d\n', s.Value);

fig = uifigure('Position', [100 100 520 300]);
T = table(["ann";"bob";"cy"], [34;28;45], [true;false;true], ...
    'VariableNames', {'name','age','active'});
t = uitable(fig, 'Position', [20 20 480 260], 'Data', T, ...
    'ColumnEditable', [false true true], 'ColumnSortable', true);
t.CellEditCallback = @(src, evt) fprintf('row %d col %d -> %s\n', ...
    evt.Indices(1), evt.Indices(2), string(evt.NewData));
s = uistyle('BackgroundColor', [1 0.9 0.9]);
addStyle(t, s, 'row', 2);

fig = uifigure('Position', [100 100 400 300]);
p = uipanel(fig, 'Title', 'Acquisition', 'Position', [20 120 360 160]);
uilabel(p, 'Position', [15 100 120 22], 'Text', 'Rate (Hz):');
uieditfield(p, 'numeric', 'Position', [140 100 100 22], 'Value', 1000);
uibutton(p, 'Position', [15 20 100 28], 'Text', 'Start');
p.Visible = 'off';
p.Visible = 'on';

fig = uifigure('Position', [100 100 480 320]);
tg = uitabgroup(fig, 'Position', [10 10 460 300]);
t1 = uitab(tg, 'Title', 'Data');
t2 = uitab(tg, 'Title', 'Plot');
uitable(t1, 'Position', [10 10 430 250], 'Data', magic(5));
ax = uiaxes(t2, 'Position', [10 10 430 250]);
plot(ax, 1:10, rand(1,10));
tg.SelectionChangedFcn = @(s,e) fprintf('now on %s\n', e.NewValue.Title);

fig = uifigure('Position', [100 100 360 300]);
g = uigauge(fig, 'circular', 'Position', [80 60 200 200], ...
    'Limits', [0 100], ...
    'ScaleColors', {'green', 'yellow', 'red'}, ...
    'ScaleColorLimits', [0 60; 60 85; 85 100]);
for v = 0:5:100
    g.Value = v;
    drawnow limitrate
end

fig = uifigure('Position', [100 100 340 260]);
k = uiknob(fig, 'continuous', 'Position', [60 80 100 100], 'Limits', [0 10]);
lbl = uilabel(fig, 'Position', [200 120 120 22], 'Text', 'gain 0.00');
k.ValueChangingFcn = @(s, e) set(lbl, 'Text', sprintf('gain %.2f', e.Value));
kd = uiknob(fig, 'discrete', 'Position', [200 30 60 60], ...
    'Items', {'Low','Med','High'});

fig = uifigure('Position', [100 100 360 200]);
uibutton(fig, 'Position', [20 20 120 28], 'Text', 'Validate', ...
    'ButtonPushedFcn', @(s,e) doCheck(fig));
function doCheck(fig)
    uialert(fig, 'Sample rate must be positive.', 'Invalid input', ...
        'Icon', 'error');
end

fig = uifigure('Position', [100 100 360 200]);
choice = uiconfirm(fig, 'Delete all results?', 'Confirm delete', ...
    'Options', {'Delete', 'Cancel'}, ...
    'DefaultOption', 2, 'CancelOption', 2, 'Icon', 'warning');
if strcmp(choice, 'Delete')
    disp('deleting...');
end

fig = uifigure('Position', [100 100 360 200]);
d = uiprogressdlg(fig, 'Title', 'Processing', 'Cancelable', 'on', ...
    'ShowPercentage', 'on');
cleanup = onCleanup(@() close(d));
for k = 1:100
    if d.CancelRequested
        break
    end
    d.Value = k / 100;
    d.Message = sprintf('Step %d of 100', k);
    pause(0.02);
end

filters = {'*.csv', 'CSV files (*.csv)'; '*.mat', 'MAT-files (*.mat)'; '*.*', 'All files'};
[file, folder] = uigetfile(filters, 'Select a data file');
if isequal(file, 0)
    disp('cancelled');
else
    full = fullfile(folder, file);
    disp(full);
end

[file, folder] = uiputfile('*.csv', 'Save results as', 'results.csv');
if ~isequal(file, 0)
    writetable(array2table(magic(4)), fullfile(folder, file));
    fprintf('saved %s\n', fullfile(folder, file));
end

folder = uigetdir(pwd, 'Select a data folder');
if isequal(folder, 0)
    disp('cancelled');
else
    files = dir(fullfile(folder, '*.csv'));
    fprintf('%d CSV files found\n', numel(files));
end

prompts = {'Sample rate (Hz):', 'Duration (s):'};
defaults = {'1000', '10'};
answer = inputdlg(prompts, 'Acquisition settings', [1 40], defaults);
if isempty(answer)
    disp('cancelled');
else
    fs = str2double(answer{1});
    dur = str2double(answer{2});
    [fs dur]
end

msgbox('Processing complete.', 'Done', 'help');
f = msgbox('Please wait...', 'Status');
pause(1);
delete(f);
uiwait(msgbox('Click OK to continue', 'Step 1', 'modal'));

answer = questdlg('Overwrite existing results?', 'Confirm', ...
    'Overwrite', 'Rename', 'Cancel', 'Cancel');
switch answer
    case 'Overwrite'
        disp('overwriting');
    case 'Rename'
        disp('renaming');
    otherwise
        disp('cancelled');
end

files = {'run1.mat', 'run2.mat', 'run3.mat'};
[idx, ok] = listdlg('ListString', files, ...
    'PromptString', 'Select files to load:', ...
    'SelectionMode', 'multiple', 'Name', 'Load data');
if ok
    selected = files(idx);
    disp(selected);
end

f = waitbar(0, 'Starting...', 'Name', 'Processing');
cleanup = onCleanup(@() close(f));
n = 50;
for k = 1:n
    pause(0.02);
    waitbar(k/n, f, sprintf('Step %d of %d', k, n));
end

f = figure('Position', [200 200 320 160], 'MenuBar', 'none');
txt = uicontrol(f, 'Style', 'text', 'Position', [20 100 260 22], ...
    'String', 'value: 0');
uicontrol(f, 'Style', 'slider', 'Position', [20 60 260 20], ...
    'Min', 0, 'Max', 10, 'Value', 0, ...
    'Callback', @(src, evt) set(txt, 'String', sprintf('value: %.2f', src.Value)));

fig = uifigure('Name', 'Editor', 'Position', [200 200 400 260]);
fileMenu = uimenu(fig, 'Text', '&File');
uimenu(fileMenu, 'Text', '&Open', 'Accelerator', 'O', ...
    'MenuSelectedFcn', @(s,e) uigetfile('*.mat'));
uimenu(fileMenu, 'Text', '&Save', 'Accelerator', 'S', ...
    'MenuSelectedFcn', @(s,e) disp('save'));
uimenu(fileMenu, 'Text', 'E&xit', 'Separator', 'on', ...
    'MenuSelectedFcn', @(s,e) close(fig));

fig = uifigure('Position', [200 200 300 160], 'Name', 'Choose');
uibutton(fig, 'Position', [100 60 100 30], 'Text', 'Continue', ...
    'ButtonPushedFcn', @(s,e) uiresume(fig));
uiwait(fig, 30);
if isvalid(fig)
    disp('continue pressed or timed out');
    close(fig);
else
    disp('window was closed');
end
